"""Fetch citation counts for every publication from Semantic Scholar and write _data/citations.yml.

Runs weekly from .github/workflows/citations.yml, or by hand:  python .github/scripts/fetch_citations.py

Papers with a `doi:` in their front matter are looked up by DOI (one batch request); that result
is written immediately. Papers without a DOI are then looked up by title, one request each, and a
match is accepted only if the returned title is nearly identical. Title lookups that keep hitting
the rate limit are skipped and retried on the next run. Papers nothing indexes get no entry.
Standard library only. Optional: set S2_API_KEY for a higher rate limit.
"""
import glob, json, os, re, sys, time, difflib, datetime
import urllib.request, urllib.parse, urllib.error

ROOT = os.path.dirname(os.path.dirname(os.path.dirname(os.path.abspath(__file__))))
PUB_DIR = os.path.join(ROOT, "_publications")
OUT = os.path.join(ROOT, "_data", "citations.yml")
API = "https://api.semanticscholar.org/graph/v1"
FIELDS = "citationCount,title,url"
HEADERS = {"User-Agent": "albertojaspe.net citation updater (github action)"}
if os.environ.get("S2_API_KEY"):
    HEADERS["x-api-key"] = os.environ["S2_API_KEY"]
PAUSE = 1.5 if "x-api-key" in HEADERS else 4.0   # seconds between requests


def log(msg):
    print(msg, flush=True)


def front_matter(path):
    text = open(path, encoding="utf-8").read()
    m = re.match(r"^---\r?\n(.*?)\r?\n---", text, re.S)
    return m.group(1) if m else ""


def field(fm, name):
    m = re.search(r"^%s:\s*(.+?)\s*$" % re.escape(name), fm, re.M)
    if not m:
        return None
    v = m.group(1).strip()
    if len(v) >= 2 and v[0] == v[-1] and v[0] in "\"'":
        v = v[1:-1]
    return v or None


class RateLimited(Exception):
    pass


def request(url, data=None, retries=3):
    """GET/POST JSON. Returns None on 404. Raises RateLimited after repeated 429s."""
    for attempt in range(retries):
        try:
            req = urllib.request.Request(url, data=data, headers={**HEADERS, "Content-Type": "application/json"})
            with urllib.request.urlopen(req, timeout=60) as r:
                return json.loads(r.read().decode("utf-8"))
        except urllib.error.HTTPError as e:
            if e.code == 404:
                return None
            if e.code in (429, 500, 502, 503) and attempt < retries - 1:
                wait = 8 * (2 ** attempt)   # 8 s, then 16 s
                log("  HTTP %d, waiting %ds" % (e.code, wait)); time.sleep(wait); continue
            if e.code == 429:
                raise RateLimited()
            raise
    raise RateLimited()


def norm(s):
    return re.sub(r"[^a-z0-9]+", " ", (s or "").lower()).strip()


HIST = os.path.join(os.path.dirname(OUT), "citations_history.yml")


def load_previous():
    """Counts from the last run, used to carry a paper over when its lookup is rate limited."""
    prev = {}
    if not os.path.exists(OUT):
        return prev
    text = open(OUT, encoding="utf-8").read()
    for m in re.finditer(r"^  (\S+):\n    count: (\d+)\n(?:    url: (\S*)\n)?    match: (\w+)", text, re.M):
        prev[m.group(1)] = {"count": int(m.group(2)), "url": m.group(3) or "", "match": m.group(4)}
    return prev


def load_history():
    """Snapshots as a list of (date, total, {code: count}), oldest first."""
    snaps = []
    if not os.path.exists(HIST):
        return snaps
    text = open(HIST, encoding="utf-8").read()
    for m in re.finditer(r"^- date: (\d{4}-\d{2}-\d{2})\n  total: (\d+)\n  papers: \{([^}]*)\}", text, re.M):
        papers = {}
        for pair in m.group(3).split(","):
            if ":" in pair:
                code, n = pair.rsplit(":", 1)
                papers[code.strip()] = int(n)
        snaps.append((m.group(1), int(m.group(2)), papers))
    return snaps


def write_history(results, total, keep_days=800):
    """Append today's snapshot (replacing one of the same day) and drop snapshots older than keep_days."""
    today = datetime.date.today()
    snaps = [s for s in load_history() if s[0] != today.isoformat()
             and (today - datetime.date.fromisoformat(s[0])).days <= keep_days]
    snaps.append((today.isoformat(), total, {c: r["count"] for c, r in results.items()}))
    lines = ["# Generated by .github/scripts/fetch_citations.py: one snapshot per run, oldest first. Do not edit by hand.",
             "# The site shows the difference between the current counts and the newest snapshot that is at least 30 days old."]
    for date, tot, papers in snaps:
        lines.append("- date: %s" % date)
        lines.append("  total: %d" % tot)
        lines.append("  papers: {%s}" % ", ".join("%s: %d" % (c, papers[c]) for c in sorted(papers)))
    with open(HIST, "w", encoding="utf-8", newline="\n") as f:
        f.write("\n".join(lines) + "\n")
    return len(snaps)


def write_output(results):
    counts = sorted((r["count"] for r in results.values()), reverse=True)
    h_index = sum(1 for i, c in enumerate(counts) if c >= i + 1)
    lines = [
        "# Generated by .github/scripts/fetch_citations.py (weekly GitHub Action). Do not edit by hand.",
        "source: Semantic Scholar",
        "updated: %s" % datetime.date.today().isoformat(),
        "indexed: %d" % len(results),
        "total: %d" % sum(counts),
        "h_index: %d" % h_index,
        "papers:",
    ]
    for code in sorted(results):
        r = results[code]
        lines += ["  %s:" % code, "    count: %d" % r["count"], "    url: %s" % r["url"], "    match: %s" % r["match"]]
    os.makedirs(os.path.dirname(OUT), exist_ok=True)
    with open(OUT, "w", encoding="utf-8", newline="\n") as f:
        f.write("\n".join(lines) + "\n")
    return sum(counts), h_index


papers = []
for path in sorted(glob.glob(os.path.join(PUB_DIR, "*.md"))):
    fm = front_matter(path)
    if re.search(r"^published:\s*false", fm, re.M):
        continue   # hidden entries are not built, so they are not counted either
    papers.append({"code": os.path.basename(path)[:-3], "doi": field(fm, "doi"), "title": field(fm, "title")})

results = {}
previous = load_previous()

# 0. The Semantic Scholar author profile (one request): papers claimed there are matched by DOI, then by title.
#    This is the primary source; the DOI batch and the title search below only cover what the profile lacks.
AUTHOR_ID = "12040242"
try:
    prof = request(API + "/author/%s/papers?fields=paperId,title,citationCount,externalIds,url&limit=500" % AUTHOR_ID)
    prof_papers = (prof or {}).get("data") or []
    by_doi = {((p.get("externalIds") or {}).get("DOI") or "").lower(): p for p in prof_papers if (p.get("externalIds") or {}).get("DOI")}
    by_title = {norm(p.get("title")): p for p in prof_papers if p.get("title")}
    for p in papers:
        hit = by_doi.get((p["doi"] or "").lower()) if p["doi"] else None
        if not hit and p["title"]:
            cand = by_title.get(norm(p["title"]))
            if not cand:
                best = max(prof_papers, key=lambda q: difflib.SequenceMatcher(None, norm(q.get("title")), norm(p["title"])).ratio(), default=None)
                if best and difflib.SequenceMatcher(None, norm(best.get("title")), norm(p["title"])).ratio() >= 0.92:
                    cand = best
            hit = cand
        if hit and hit.get("citationCount") is not None:
            results[p["code"]] = {"count": int(hit["citationCount"]), "url": hit.get("url", ""), "match": "profile"}
    log("author profile: %d papers listed, %d of %d site entries matched" % (len(prof_papers), len(results), len(papers)))
    time.sleep(PAUSE)
except RateLimited:
    log("author profile request rate limited, falling back to DOI and title lookups")

# 1. DOI batch (one request), written right away
with_doi = [p for p in papers if p["doi"]]
if with_doi:
    body = json.dumps({"ids": ["DOI:" + p["doi"] for p in with_doi]}).encode("utf-8")
    batch = request(API + "/paper/batch?fields=" + FIELDS, data=body) or []
    for p, hit in zip(with_doi, batch):
        if hit and hit.get("citationCount") is not None:
            results[p["code"]] = {"count": int(hit["citationCount"]), "url": hit.get("url", ""), "match": "doi"}
    log("DOI batch: %d of %d found" % (len(results), len(with_doi)))
    write_output(results)
    time.sleep(PAUSE)

# 2. Title match for the rest (one request per paper; skipped on persistent rate limiting)
skipped = []
for p in papers:
    if p["code"] in results or not p["title"]:
        continue
    try:
        hit = request(API + "/paper/search/match?query=" + urllib.parse.quote(p["title"]) + "&fields=" + FIELDS)
    except RateLimited:
        skipped.append(p["code"])
        if p["code"] in previous:   # keep last week's number rather than dropping the paper
            results[p["code"]] = dict(previous[p["code"]], match="cached")
            log("  rate limited, keeping the previous count for %s" % p["code"])
        else:
            log("  rate limited, skipping %s" % p["code"])
        continue
    finally:
        time.sleep(PAUSE)
    data = (hit or {}).get("data") or []
    if not data:
        log("  no match: %s" % p["code"]); continue
    best = data[0]
    similarity = difflib.SequenceMatcher(None, norm(best.get("title")), norm(p["title"])).ratio()
    if similarity >= 0.92 and best.get("citationCount") is not None:
        results[p["code"]] = {"count": int(best["citationCount"]), "url": best.get("url", ""), "match": "title"}
        log("  title match: %s (%d)" % (p["code"], results[p["code"]]["count"]))
    else:
        log("  rejected match for %s (similarity %.2f)" % (p["code"], similarity))

total, h_index = write_output(results)
snapshots = write_history(results, total)
log("indexed %d of %d papers, total citations %d, h-index %d; %d snapshots in the history" % (len(results), len(papers), total, h_index, snapshots))
if skipped:
    log("skipped because of rate limiting (retried next run): " + ", ".join(skipped))
